import sys
L=sys.stdin.read().split('\n');t=int(L[0]);P={')':'(',']':'[','}':'{'}
out=[]
for s in L[1:1+t]:
    st=[];ok=True
    for c in s.strip():
        if c in '([{': st.append(c)
        elif not st or st.pop()!=P[c]: ok=False; break
    out.append('YES' if ok and not st else 'NO')
print('\n'.join(out))

